#!/usr/bin/env node
// Vendors the website's splash into the boot (track FG; DESIGN.md §8 "The boot splash"): the module the website's
// loading window runs — vibefield-dotdev's lib/splash/vibefield-splash.js, itself GENERATED by vibefield-splash's
// bake from the look "Wormhole · edited" — and the pictures that stand in for it before its first frame and where
// there is no WebGPU (public/brand/). Each source is pinned by its sha256 in SOURCE below: a new bake reaches the
// product only as a deliberate move of its pin, never by a copy.
//   node tooling/splash/vendor.mjs [--from <vibefield-dotdev>]          writes packages/field-app/src/boot/splash/
//   node tooling/splash/vendor.mjs --check [--from <vibefield-dotdev>]  fails if a committed file differs
// `--from` defaults to $VIBEFIELD_DOTDEV, then ../vibefield-dotdev beside this checkout. The module's header names
// every pin and its own body's hash, so field-app's splash-vendor test holds the committed files to it without the
// website's checkout.

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..", "..");
const OUT = join(ROOT, "packages/field-app/src/boot/splash");

// vibefield-dotdev 37eb2c3, "Open on VibeField's splash and its cutting mat, in daylight": the revision the splash
// and its pictures last changed at.
const SOURCE = {
  revision: "37eb2c3",
  module: {
    from: "lib/splash/vibefield-splash.js",
    to: "vibefield-splash.js",
    sha256: "e77268f39c7bb2bf7afa4130b7d5b8c387755fb173205f983314dfb24f57186f",
  },
  pictures: [
    {
      from: "public/brand/mark-white.webp",
      to: "assets/mark-white.webp",
      sha256: "3f23ae70e96e24a5874bd892a4fe4574a6bc6e77ddb204d9b5884e429ad85c21",
    },
    {
      from: "public/brand/splash-still-wide.avif",
      to: "assets/splash-still-wide.avif",
      sha256: "dea4d0a013a734e1c3a502782f62020991083996c6dfa73f7f604ddb85f708e5",
    },
    {
      from: "public/brand/splash-still-tall.avif",
      to: "assets/splash-still-tall.avif",
      sha256: "97ea2d8601ebfe561d3826bb7d1b06d2cc32e5a0a52d4570a7a508e8f0ad09e3",
    },
  ],
};

const sha256 = (bytes) => createHash("sha256").update(bytes).digest("hex");

const args = process.argv.slice(2);
const check = args.includes("--check");
const fromAt = args.indexOf("--from");
const from = resolve(
  fromAt >= 0
    ? args[fromAt + 1]
    : (process.env.VIBEFIELD_DOTDEV ?? join(ROOT, "..", "vibefield-dotdev")),
);

function source(entry) {
  const path = join(from, entry.from);
  if (!existsSync(path)) throw new Error(`${path} is missing — pass --from <vibefield-dotdev>`);
  const bytes = readFileSync(path);
  const got = sha256(bytes);
  if (got !== entry.sha256)
    throw new Error(
      `${entry.from} is ${got}, not its pin ${entry.sha256}: a new bake is a deliberate move of SOURCE's pin`,
    );
  return bytes;
}

// The module as the website ships it, under a header naming every pin (the pictures are copied as they are).
const body = source(SOURCE.module).toString("utf8");
const header = [
  `// GENERATED by tooling/splash/vendor.mjs from vibefield-dotdev ${SOURCE.revision} — do not edit (DESIGN.md §8 "The boot splash").`,
  `// sha256 ${SOURCE.module.sha256} ${SOURCE.module.from} → ${SOURCE.module.to} (body sha256 ${sha256(body)})`,
  ...SOURCE.pictures.map((p) => `// sha256 ${p.sha256} ${p.from} → ${p.to}`),
  "",
].join("\n");
const outputs = [
  [SOURCE.module.to, Buffer.from(`${header}\n${body}`, "utf8")],
  ...SOURCE.pictures.map((p) => [p.to, source(p)]),
];

let stale = 0;
for (const [rel, bytes] of outputs) {
  const path = join(OUT, rel);
  if (check) {
    if (!existsSync(path) || !readFileSync(path).equals(bytes)) {
      console.error(`stale: ${path}`);
      stale++;
    }
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, bytes);
    console.log(`wrote ${path}`);
  }
}
if (stale > 0) {
  console.error(`${stale} vendored file(s) differ — run node tooling/splash/vendor.mjs`);
  process.exit(1);
}
